        return "This is a secured endpoint!";
    }
}"},{"order":38,"type":"subheading","text":"Testing the Implementation"},{"order":39,"type":"paragraph","text":"1.  **Start the Spring Boot application.**"},{"order":40,"type":"paragraph","text":"2.  **Authenticate:** Send a POST request to `/api/auth/authenticate` with the following JSON payload:"},{"order":41,"type":"code","text":"{
